import sys
from collections import deque

def main():
    N, D = map(int, sys.stdin.readline().split())
    coords = []
    for _ in range(N):
        x, y = map(int, sys.stdin.readline().split())
        coords.append((x, y))

    D_squared = D * D
    adj = [[] for _ in range(N)]

    for i in range(N):
        xi, yi = coords[i]
        for j in range(N):
            if i == j:
                continue
            dx = xi - coords[j][0]
            dy = yi - coords[j][1]
            dist_sq = dx * dx + dy * dy
            if dist_sq <= D_squared:
                adj[i].append(j)

    visited = [False] * N
    q = deque()
    q.append(0)
    visited[0] = True

    while q:
        current = q.popleft()
        for neighbor in adj[current]:
            if not visited[neighbor]:
                visited[neighbor] = True
                q.append(neighbor)

    for result in visited:
        print("Yes" if result else "No")

if __name__ == "__main__":
    main()
```

