import sys

def main():
    input = sys.stdin.read
    data = input().splitlines()

    N, Q = map(int, data[0].split())
    history = [(1, 0)]
    head_x, head_y = 1, 0

    for line in data[1:]:
        parts = line.split()
        if parts[0] == '1':
            C = parts[1]
            if C == 'R':
                head_x += 1
            elif C == 'L':
                head_x -= 1
            elif C == 'U':
                head_y += 1
            elif C == 'D':
                head_y -= 1
            history.append((head_x, head_y))
        else:
            p = int(parts[1])
            m = len(history) - 1
            if m >= p - 1:
                idx = m - (p - 1)
                x, y = history[idx]
            else:
                x = 1 + (p - 1 - m)
                y = 0
            print(f"{x} {y}")

if __name__ == "__main__":
    main()
```

