import sys

class FenwickTree:
    def __init__(self, size):
        self.size = size
        self.tree = [0] * (self.size + 2)  # 1-based indexing

    def add(self, index, delta):
        while index <= self.size:
            self.tree[index] += delta
            index += index & -index

    def query(self, index):
        res = 0
        while index > 0:
            res += self.tree[index]
            index -= index & -index
        return res

def main():
    input = sys.stdin.read().split()
    ptr = 0
    N = int(input[ptr])
    ptr += 1
    intervals = []
    for _ in range(N):
        a = int(input[ptr])
        b = int(input[ptr + 1])
        ptr += 2
        if a > b:
            a, b = b, a
        intervals.append((a, b))
    intervals.sort()
    max_val = 2 * N
    ft = FenwickTree(max_val)
    for x, y in intervals:
        if y - 1 >= 1:
            q1 = ft.query(y - 1)
        else:
            q1 = 0
        q2 = ft.query(x)
        if q1 - q2 > 0:
            print("Yes")
            return
        ft.add(y, 1)
    print("No")

if __name__ == "__main__":
    main()
```

